def posizioni_dai_ruoli(apps, schema_editor):
    """Ogni ruolo scritto a mano diventa una posizione dell'azienda (con il reparto più frequente), col suo organico."""
    Dipendente, Posizione = apps.get_model("personale", "Dipendente"), apps.get_model("personale", "Posizione")
    gruppi = {}
    for d in Dipendente.objects.exclude(ruolo=""):
        gruppi.setdefault((d.azienda_id, d.ruolo.strip()), []).append(d)
    for (azienda, nome), persone in gruppi.items():
        reparti = [d.reparto_id for d in persone if d.reparto_id]
        reparto = max(set(reparti), key=reparti.count) if reparti else None
        attivi = sum(1 for d in persone if d.attivo)
        p = Posizione.objects.create(azienda_id=azienda, nome=nome[:100], reparto_id=reparto, organico=max(attivi, 1))
        Dipendente.objects.filter(pk__in=[d.pk for d in persone]).update(posizione=p)


